# Perform BFS from node '1679091c5a' to find nodes at exactly depth 4
from collections import deque

start_node = '1679091c5a'

# BFS to track nodes at each depth
def bfs_depth(graph, start, target_depth):
    visited = {start}  # Track all visited nodes
    current_depth = 0
    current_level = {start}

    while current_depth < target_depth:
        next_level = set()
        for node in current_level:
            if node in graph:
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        next_level.add(neighbor)
                        visited.add(neighbor)
        current_level = next_level
        current_depth += 1
        print(f"Depth {current_depth}: {sorted(current_level)}")

    return current_level

result = bfs_depth(graph, start_node, 4)
print(f"\nNodes at exactly depth 4: {sorted(result)}")
